    return p.returncode, p.stdout, p.stderr
def new(args, inp=None):
    p = subprocess.run(["python3","src/main.py"]+args, input=inp, capture_output=True, timeout=5)
    return p.returncode, p.stdout, p.stderr.replace(b"src/main.py", b"./executable")
tests = [
    ((["a","b","c"], None)),
    (([], b".output /nonexistent_dir/file\nselect 1;")),
]
for args, inp in tests:
    rc1,out1,err1 = orig(args, inp)
    rc2,out2,err2 = new(args, inp)
    print("OK" if (rc1==rc2 and out1==out2 and err1==err2) else "DIFF", args)
    if not (rc1==rc2 and out1==out2 and err1==err2):
        print(" orig", rc1, out1[:500], err1[:500])
        print(" new ", rc2, out2[:500], err2[:500])
